// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    uint public gasSink;
    bool private __entered;

    receive() external payable {
        // consumes far more than the 2300-gas transfer stipend
        for (uint i = 0; i < 5; i++) {
            gasSink += msg.value + i;
        }
        if (!__entered) {
            __entered = true;
            c.withdraw(msg.value);
        }
    }

    function setUp() public {
        c = new SimpleWallet();
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(amount > 0 && amount < address(this).balance);
        vm.deal(address(this), amount * 3);

        // fund c so a full withdrawal is possible
        (bool okDep,) = address(c).call{value: amount}("");
        assertTrue(okDep);
        uint256 before = address(c).balance;

        // c.withdraw sends via transfer/call to msg.sender == this test
        // contract, whose receive() needs more than 2300 gas. A real
        // transfer must therefore fail and the withdraw must revert.
        bool ok; try c.withdraw(amount) { ok = true; } catch { ok = false; }

        // General rule: withdrawing to a gas-hungry (or reverting) receiver
        // must be an unsuccessful call; c must revert rather than silently
        // ignore the failed payout.
        assertTrue(!ok && address(c).balance == before);
    }
}
